class PokeAPI{constructor(){this.baseURL="https://pokeapi.co/api/v2/",this.cache=new Map,this.cacheTimeout=3e5}clearExpiredCache(){var t,e,a=Date.now();for([t,e]of this.cache.entries())e.timestamp&&a-e.timestamp>this.cacheTimeout&&this.cache.delete(t)}async fetchPokemonList(t=20,e=0){this.clearExpiredCache();var a=`pokemon-list-${t}-`+e,s=this.cache.get(a);if(s&&Date.now()-s.timestamp<this.cacheTimeout)return s.data;s=this.baseURL+`pokemon?limit=${t}&offset=`+e;try{var o,i=await fetch(s);if(i.ok)return o=await i.json(),this.cache.set(a,{data:o,timestamp:Date.now()}),o;throw new Error("Erro ao buscar lista de Pokémons: "+i.status)}catch(t){throw console.error("Erro ao buscar lista de Pokémons:",t),t}}}